-- ====================================================================
-- REGISTRO DE CONTEO INICIAL EN AUDITORIAS DE CIERRE PARA AGOSTO 2026
-- ====================================================================
INSERT INTO public.registro_auditorias_cierres (
    id_auditoria, id_periodo, fecha_cierre, codigo_insumo, tipo_registro,
    cantidad_sistema, cantidad_fisica, diferencia, estado, costo_unitario_snapshot
)
SELECT 
    gen_random_uuid(),
    p.id_periodo,
    '2026-08-01 00:00:00+00'::timestamptz,
    c.codigo_insumo,
    'INVENTARIO_INICIAL',
    c.stock_actual,
    c.stock_actual,
    0,
    'APROBADO',
    c.costo_unitario
FROM public.catalogo_insumos c
CROSS JOIN (SELECT id_periodo FROM public.periodos_inventario WHERE mes_periodo = '2026-08' LIMIT 1) p;